from sqlalchemy import Column, Integer, String, DateTime, JSON, Boolean, Text, funcfrom .database import Baseclass User(Base):    __tablename__ = "users"    id = Column(Integer, primary_key=True, index=True)    username = Column(String, unique=True, index=True, nullable=False)    hashed_password = Column(String, nullable=False)    is_admin = Column(Boolean, default=False)    credits = Column(Integer, default=0)class SearchLog(Base):    __tablename__ = "search_logs"    id = Column(Integer, primary_key=True, index=True)    user_id = Column(Integer, nullable=False)    query_type = Column(String, nullable=False)    query_value = Column(String, nullable=False)    credits_used = Column(Integer, nullable=False)    result_summary = Column(Text)    raw_result = Column(JSON)    ip_address = Column(String)    created_at = Column(DateTime(timezone=True), server_default=func.now())